<?php /** Template Name: Client Portal */ if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/client-portal/')));exit;}if(tuff_beatz_is_producer_user()){wp_safe_redirect(home_url('/producer-portal/'));exit;}$u=wp_get_current_user();$projects=tuff_beatz_client_projects($u->ID);get_header();?>
<main class="tb-hub"><section class="tb-hub-hero"><div class="container"><p class="eyebrow">TUFF BEATZ CLIENT PORTAL</p><h1>Welcome back, <?php echo esc_html($u->display_name);?></h1><p>Your projects, files, reviews, contracts, payments and delivery — all in one place.</p><div class="tb-hub-actions"><a class="btn btn-gold" href="<?php echo esc_url(home_url('/start-a-project/'));?>">Start New Project</a><a class="btn btn-outline" href="<?php echo esc_url(wp_logout_url(home_url('/')));?>">Log Out</a></div></div></section>
<section class="section"><div class="container"><div class="tb-hub-heading"><div><p class="tb-card-kicker">MY WORKSPACE</p><h2>My Projects</h2></div><span><?php echo esc_html(count($projects));?> project<?php echo count($projects)===1?'':'s';?></span></div><?php if($projects):?><div class="tb-project-grid"><?php foreach($projects as $p):$id=$p->ID;$status=get_post_meta($id,'_tb_request_status',true)?:'new';$service=get_post_meta($id,'_tb_request_service',true);$progress=tuff_beatz_project_progress_percent($id);$services=tuff_beatz_services();?><article class="tb-project-card"><div class="tb-project-card-top"><span class="tb-status tb-status--<?php echo esc_attr($status);?>"><?php echo esc_html(tuff_beatz_request_status_label($status));?></span><small>#<?php echo esc_html($id);?></small></div><h3><?php echo esc_html($p->post_title);?></h3><p><?php echo esc_html($services[$service]??$service);?></p><div class="tb-progress"><i style="width:<?php echo esc_attr($progress);?>%"></i></div><div class="tb-project-card-foot"><span><?php echo esc_html($progress);?>% complete</span><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($id));?>">Open Project →</a></div></article><?php endforeach;?></div><?php else:?><div class="tb-empty-hub"><h3>No projects yet</h3><p>Start your first TUFF BEATZ project and your workspace will appear here automatically.</p><a class="btn btn-gold" href="<?php echo esc_url(home_url('/start-a-project/'));?>">Start a Project</a></div><?php endif;?></div></section></main><?php get_footer();?>